          btn.classList.add('bg-slate-800', 'text-slate-300');
        }
      });

      const activeView = document.getElementById(`view${viewId.charAt(0).toUpperCase() + viewId.slice(1)}`);
      if (activeView) activeView.classList.remove('hidden');

      const activeBtn = document.getElementById(`navBtn${viewId.charAt(0).toUpperCase() + viewId.slice(1)}`);
      if (activeBtn) {
        activeBtn.classList.remove('bg-slate-800', 'text-slate-300');
        activeBtn.classList.add('bg-sky-600', 'text-white');
      }

      if (viewId === 'models') loadModels();
    }

    // Models Logic
    async function loadModels() {
      const grid = document.getElementById('modelsGrid');
      const loading = document.getElementById('modelsLoadingState');
      const empty = document.getElementById('noModelsState');

      grid.innerHTML = '';
      loading.classList.remove('hidden');
      empty.classList.add('hidden');

      try {
        const resp = await fetch('/models/list');
        const data = await resp.json();
        const models = data.models || [];

        loading.classList.add('hidden');
        if (models.length === 0) {
          empty.classList.remove('hidden');
          return;
        }

        models.forEach(m => {
          const card = document.createElement('div');
          card.className = `p-4 rounded-xl border ${m.loaded ? 'border-emerald-500/30 bg-emerald-500/5' : 'border-slate-800 bg-slate-950'} flex justify-between items-center`;
          card.innerHTML = `
            <div class="min-w-0">
              <div class="text-sm font-bold text-slate-100 truncate" title="${m.display_name}">${m.display_name}</div>
              <div class="text-[10px] uppercase tracking-wider ${m.loaded ? 'text-emerald-400' : 'text-slate-500'} font-bold">
                ${m.loaded ? '● Loaded' : '○ Available'}
              </div>
            </div>
            <button onclick="loadModel('${m.key}')" class="px-3 py-1.5 text-[10px] rounded bg-slate-800 hover:bg-sky-600 transition ${m.loaded ? 'hidden' : ''}">
              Load
            </button>
          `;
          grid.appendChild(card);
        });
      } catch (err) {
        console.error(err);
        loading.classList.add('hidden');
      }
    }

    async function refreshModels() {
      const btn = document.getElementById('btnRefreshModels');
      const icon = document.getElementById('refreshIcon');
      const text = document.getElementById('refreshText');

      btn.disabled = true;
      icon.innerHTML = '<div class="spinner"></div>';
      text.innerText = 'Refreshing...';

      try {
        await fetch('/models/refresh', { method: 'POST' });
        await loadModels();
      } catch (err) {
        alert('Failed to refresh models.');
      } finally {
        btn.disabled = false;
        icon.innerHTML = '<svg class="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M4 4v5h.582m15.356 2A8.001 8.001 0 004.582 9m0 0H9m11 11v-5h-.581m0 0a8.003 8.003 0 01-15.357-2m15.357 2H15"></path></svg>';
        text.innerText = 'Refresh Models';
      }
    }

